from pathlib import Path
TODAY='2026-06-18'
def header(title): return f"# {title}\n\n> - 引用级别：✅可供学习参考\n> - 最后更新：{TODAY}\n\n"
def write(path,text): Path(path).write_text(text.strip()+"\n", encoding='utf-8')
def article(title,path,pos,concepts,asks,triage,cats,scenarios,analysis):
 c='\n\n'.join(f"### {i+1}. {h}\n\n{b}" for i,(h,b) in enumerate(concepts)); a='\n'.join(f"- {x}" for x in asks)
 t='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in triage); ca='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} |" for x in cats)
 sc='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} |" for x in scenarios); an='\n'.join(f"- **{k}：** {v}" for k,v in analysis)
 write(path, header(title)+f'''## 一句话定位\n\n{pos}\n\n## 一、准确解释：三个概念分别是什么\n\n{c}\n\n## 二、药店咨询首先要问什么\n\n{a}\n\n## 三、轻症、需药师判断、应就医的分层\n\n| 分层 | 典型表现 | 药店/平台可以做什么 | 不应做什么 |\n|---|---|---|---|\n{t}\n\n## 四、常见品类与药店咨询口径\n\n| 品类/服务 | 适合讨论的场景 | 药师提醒点 |\n|---|---|---|\n{ca}\n\n## 五、即时零售医药场景拆解\n\n| 场景 | 用户需求 | 平台/药店承接点 |\n|---|---|---|\n{sc}\n\n## 六、对平台、药店、药企的业务分析\n\n{an}\n''')

article('乙肝与抗病毒药物基础','08-疾病与医学基础/补充资料/乙肝与抗病毒药物基础.md','本文回答：乙肝、慢性乙肝和抗病毒治疗在药店复购/DTP场景中应如何理解。核心判断是：乙肝管理不是单次买药，而是围绕病毒复制、肝功能、长期抗病毒依从性和定期随访形成的处方药服务场景；平台和药店不能替代医生决定是否用药或停药。',
[('乙肝病毒感染：不是所有感染者都需要同样治疗','乙肝由乙型肝炎病毒感染引起，可能表现为急性感染、慢性感染或携带状态。是否需要治疗取决于病毒复制、肝功能、肝纤维化/肝硬化风险、年龄和其他临床因素。'),('慢性乙肝：长期随访比短期症状更重要','许多慢性乙肝患者没有明显症状，但仍需要定期复查肝功能、HBV DNA、肝脏影像或其他指标。药店复购不能替代复诊。'),('抗病毒药物：长期依从性和停药风险是核心','核苷/核苷酸类似物等抗病毒药物通常需要长期规范使用。漏服、自行停药或随意换药可能带来病毒反弹和肝炎活动风险。'),('乙肝用药场景：处方、医保、DTP和隐私都重要','乙肝药品复购常涉及处方、医保支付、隐私保护和长期依从性服务。')],
['用户是乙肝感染咨询、已有诊断复购，还是想自行购买抗病毒药。','是否有医生处方、最近肝功能/HBV DNA复查和复诊计划。','是否漏服、自行停药、换药或出现不良反应。','是否孕期、肝硬化、肾功能异常或合并其他病毒感染。','是否出现黄疸、腹胀、明显乏力、出血倾向等风险信号。'],
[('稳定复购','已有处方且按医嘱长期用药','复购提醒、依从性教育、复诊提醒','不建议自行停药'),('药师重点判断','漏服、换药、不良反应或复查不规律','提醒联系医生、核对处方和相互作用','不决定治疗方案'),('优先就医','黄疸、明显乏力、腹胀、出血倾向、孕期或肝硬化异常','提示就医','不靠平台购药处理')],
[('抗病毒处方药','已有诊断和处方的复购','长期依从性，不自行停换'),('肝功能/病毒量复查提醒','慢病随访','药店只能提醒，不能解释复杂结果'),('DTP/医保服务','长期处方药可及','核对处方、医保和隐私'),('药师咨询','漏服、不良反应、相互作用','建议联系医生')],
[('处方复购','不断药','处方/医保/库存'),('随访提醒','复查时间临近','提醒复诊'),('隐私购药','用户担心隐私','私密配送和咨询'),('风险信号','黄疸或肝病加重','就医提示')],
[('平台','乙肝入口要围绕处方复购、隐私和随访提醒，不应做“自测后购药”暗示。'),('药店','药师应强调长期依从性、漏服处理和复诊，而不是推荐保肝品替代抗病毒。'),('药企','患者教育重点是规范治疗、复诊监测和长期可及。')])

article('肿瘤特药与DTP药房基础','08-疾病与医学基础/补充资料/肿瘤特药与DTP药房基础.md','本文回答：肿瘤特药为什么需要DTP药房、患者服务和处方承接。核心判断是：肿瘤特药不是普通即时零售商品，而是围绕专科处方、支付、冷链/储存、药师随访和不良反应管理形成的院外药事服务场景。',
[('肿瘤特药：高专业度、高支付压力、高随访需求','肿瘤特药通常用于特定癌种、分期、基因检测或治疗线数，对适应症和用法要求严格。患者不能仅凭药名自行购买。'),('DTP药房：不是普通药店，而是专科药承接节点','DTP药房承担处方审核、药品储存、配送、支付协助、患者教育和随访等服务，适合连接医院处方和院外用药。'),('不良反应管理：肿瘤药服务的核心之一','肿瘤药可能出现发热、感染、皮疹、腹泻、出血、肝肾功能异常等风险。药房需要识别并提示患者联系医生。'),('支付可及：医保、商保、慈善援助影响购药路径','肿瘤特药费用高，用户关注的不只是有无库存，还有支付方式、报销、援助和配送安全。')],
['是否有明确肿瘤诊断、专科医生处方和治疗方案。','药品是否需要冷链、特殊储存或DTP药房服务。','是否有不良反应、漏服、停药或治疗方案变化。','医保、商保、援助和处方有效期情况。','是否出现发热感染、出血、严重腹泻、呼吸困难等风险。'],
[('稳定取药','专科处方明确、DTP流程清楚','处方核验、库存、支付和配送协调','不解释治疗方案'),('药师重点判断','不良反应、漏服、支付问题、冷链要求','提醒联系医生并做药事服务','不自行建议加减药'),('优先就医','发热感染、严重不良反应、出血、治疗中断','提示联系医生或急诊','不等待平台配送')],
[('肿瘤特药','专科处方下使用','严格核对适应症和处方'),('DTP服务','院外取药和患者管理','关注冷链、支付和随访'),('不良反应咨询','治疗期间风险识别','及时联系医生'),('支付服务','医保/商保/援助','不承诺报销结果')],
[('DTP取药','医院外购药','处方、库存、冷链'),('续方复购','治疗周期用药','提醒复诊和处方有效期'),('不良反应','治疗期间不适','药师提示联系医生'),('支付咨询','费用压力','医保/商保/援助信息')],
[('平台','肿瘤特药不能做普通搜索转化，应走DTP、处方和药事服务流程。'),('药店','DTP药房的核心是处方核验、冷链、支付和随访。'),('药企','特药渠道要关注患者服务、支付可及和不良反应管理。')])

article('孕妇与哺乳期用药咨询边界','08-疾病与医学基础/补充资料/孕妇与哺乳期用药咨询边界.md','本文回答：孕妇和哺乳期用药为什么是高风险咨询场景。核心判断是：孕哺期用药不能按普通成人场景处理，任何药品推荐都必须先考虑孕周、哺乳状态、胎儿/婴儿暴露风险、疾病严重程度和医生/药师确认。',
[('孕期用药：风险取决于孕周、药物和疾病本身','孕期不同阶段对药物敏感性不同，疾病不治疗也可能带来风险。药店不能简单说“孕妇不能用药”或“天然安全”。'),('哺乳期用药：关注药物进入乳汁和婴儿反应','哺乳期用药要考虑药物是否进入乳汁、婴儿年龄、早产/疾病状态和用药时间。'),('常见小病也需要更谨慎','感冒、发热、过敏、胃肠不适、皮肤问题在孕哺期都常见，但药品选择、剂量和就医阈值不同。'),('咨询边界：药店做风险识别，不替代产科/儿科判断','药师可以解释说明书、识别高风险和建议就医，但不能替代医生决定复杂用药。')],
['孕周、是否哺乳、婴儿年龄和是否早产。','症状是什么、持续多久、严重程度和是否发热/疼痛/感染。','是否已有医生建议，是否正在使用处方药或保健品。','既往流产、妊娠合并症、肝肾功能异常或过敏史。','是否出现腹痛出血、高热、呼吸困难、严重呕吐等风险。'],
[('轻症咨询','症状轻且说明书明确可咨询','解释说明书、建议联系医生确认','不随意推荐成人药'),('药师重点判断','孕周特殊、哺乳婴儿小、用药不清','核对风险并建议医生/药师确认','不以经验替代评估'),('优先就医','出血腹痛、高热、严重呕吐、呼吸困难、胎动异常','提示就医','不靠自购药处理')],
[('说明书明确品类','医生/药师确认后使用','核对孕哺期描述'),('外用/局部用品','轻症护理','注意吸收、面积和疗程'),('营养补充','孕期营养管理','避免重复和超量'),('药师咨询','不确定是否能用','以转诊和确认优先')],
[('急用咨询','孕妇感冒腹泻过敏','先筛红旗，建议确认'),('家庭常备','孕哺期可用物品','按孕周和说明书'),('哺乳咨询','担心影响婴儿','说明风险并建议专业确认'),('就医提醒','风险信号','产科/儿科优先')],
[('平台','孕哺期标签应触发强风险提示，不能直接按成人商品排序。'),('药店','药师应先问孕周和哺乳情况，再谈品类。'),('药企','孕哺期内容必须严格遵循说明书，避免“温和安全”泛化表达。')])

article('老年用药基础与慢病复购','08-疾病与医学基础/补充资料/老年用药基础与慢病复购.md','本文回答：老年人用药和慢病复购为什么需要单独管理。核心判断是：老年用户常见多病共存、多药联用、肝肾功能下降和跌倒风险，平台复购不能只追求不断药，还要关注重复用药、相互作用、不良反应和照护人协同。',
[('老年用药：生理变化会改变风险','老年人肝肾功能、体液分布、认知和跌倒风险可能改变药物安全性。相同药物在老年人身上可能更容易出现低血压、低血糖、出血、嗜睡或跌倒。'),('多病共存：处方来自多个科室','高血压、糖尿病、冠心病、脑卒中、肾病、失眠等可能同时存在，用户常从多个医生处获得处方。'),('多药联用：重复成分和相互作用是核心风险','老年人可能同时使用处方药、OTC、中成药和保健品，药师需要核对药名、成分和服用时间。'),('慢病复购：照护人也是服务对象','很多老年复购由子女或照护人完成，平台和药店要让照护人理解剂量、频次、禁忌和异常信号。')],
['年龄、肝肾功能、近期跌倒、认知状态和照护人情况。','目前所有处方药、OTC、中成药、保健品清单。','是否有低血糖、头晕、出血、嗜睡、便秘、尿潴留等不良反应。','是否自行停药、漏服或重复购买同类药。','是否出现意识改变、跌倒、胸痛、呼吸困难或严重感染。'],
[('稳定复购','处方明确、照护清楚、无异常','复购提醒、用药清单核对','不随意替换'),('药师重点判断','多药联用、重复成分、轻微不良反应','核对相互作用和就医需求','不只按历史订单复购'),('优先就医','意识改变、跌倒、出血、严重低血糖、胸痛呼吸困难','提示就医','不靠买药处理')],
[('慢病处方药','长期复购','核对处方和用药清单'),('监测用品','血压血糖血氧等','帮助照护人记录'),('OTC/常备用品','便秘、疼痛、感冒等轻症','关注相互作用和禁忌'),('药师随访','多药联用和不良反应','建立药历意识')],
[('子女代购','照护人帮老人买药','用药清单和提醒'),('慢病复购','长期用药不断药','处方/医保/复诊'),('异常咨询','头晕跌倒低血糖','风险识别'),('家庭常备','老人常用品','避免重复和高风险品类')],
[('平台','老年复购应支持药历、照护人提醒和重复用药拦截。'),('药店','药师应主动核对全部用药，不只看本次订单。'),('药企','老年慢病教育要强调依从性、不良反应和监测。')])

article('药物相互作用与联合用药基础','08-疾病与医学基础/补充资料/药物相互作用与联合用药基础.md','本文回答：药物相互作用和联合用药为什么是药店咨询的核心风险。核心判断是：平台买药越便利，用户越容易多渠道购药和重复用药；药师服务必须帮助识别处方药、OTC、中成药、保健品之间的相互作用和重复成分。',
[('药物相互作用：一种药会影响另一种药的效果或风险','相互作用可能增强不良反应、降低疗效或改变血药浓度。它可能发生在处方药之间，也可能发生在OTC、中成药、保健品和食物之间。'),('联合用药：有时必要，但需要管理','慢病患者常需要联合用药，例如降压、降糖、调脂和抗血小板联合。联合并不一定错误，关键是是否由医生安排、是否监测、是否理解风险。'),('重复成分：OTC场景最常见的隐性风险','复方感冒药、止痛药、胃药和中成药可能含相同或相近成分。用户跨平台购买时更容易重复。'),('药历意识：平台和药店需要知道用户正在用什么','没有完整用药清单，药师很难判断相互作用。复购和咨询都应鼓励用户提供当前用药。')],
['用户正在使用的所有处方药、OTC、中成药、保健品和外用药。','是否来自多个医生或多个平台购买。','是否出现出血、低血糖、头晕、嗜睡、皮疹、胃痛等新症状。','是否有肝肾功能异常、老人、孕妇或慢病多病共存。','是否自行加量、停药、换药或同时服用多种复方药。'],
[('可咨询','用户想核对能否同服','收集用药清单，提醒说明书和医生确认','不凭单一药名判断安全'),('药师重点判断','多药联用、重复成分、老人慢病','识别高风险组合并建议就医/医生确认','不随意建议停处方药'),('优先就医','出血、严重过敏、意识改变、严重低血糖或疑似严重不良反应','提示就医','不只调整购物车')],
[('用药清单核对','多药联用用户','尽量完整收集药名和剂量'),('复方药成分识别','感冒、止痛、胃药等','避免重复成分'),('慢病药咨询','长期联合用药','关注监测和复诊'),('药师在线','不确定能否同服','建议医生或药师确认')],
[('跨平台购药','用户多渠道买药','用药清单提醒'),('复方感冒药','重复退热镇痛风险','成分核对'),('慢病多药','长期联合','药师随访'),('不良反应','新发异常症状','就医提示')],
[('平台','应建立重复成分和高风险组合提示，而不是只做关联推荐。'),('药店','药师应主动询问全部用药，尤其是老人和慢病用户。'),('药企','说明书教育要突出相互作用、禁忌和特殊人群。')])

